<template>
  <q-footer class="validation-status-bar back-white document-footer">
    <q-toolbar class="row justify-start">
      <span class="footer-filename">{{ filename }}</span>
      <q-btn
        size="md"
        flat
        dense
        class="q-ml-xs"
        @click="handleDownload"
      >
        <q-icon name="download" style="color: #8a8a8a" />
      </q-btn>
      <q-separator vertical class="q-mx-md" />

      <slot />

      <q-space />

      <template v-if="showZoom">
        <q-separator vertical class="q-mx-xs" />
        <q-btn flat dense icon="remove" class="icon-grey validation-footer-button" @click="zoomOut" />
        <q-slider
          style="width: 150px; min-width: 150px; margin: 0 8px"
          dense
          :model-value="modelValue"
          :min="zoomMin"
          :max="zoomMax"
          :step="zoomStep"
          @update:model-value="onSliderChange"
        />
        <q-btn flat dense icon="add" class="icon-grey validation-footer-plus-button" @click="zoomIn" />
      </template>
    </q-toolbar>
  </q-footer>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { downloadDocumentFile } from 'src/utils/download';
import { useImageAuth } from 'src/composables/useImageAuth';

export default defineComponent({
  name: 'DocumentFooter',
  props: {
    filename: {
      type: String,
      default: '',
    },
    docId: {
      type: String,
      default: '',
    },
    showZoom: {
      type: Boolean,
      default: true,
    },
    modelValue: {
      type: Number,
      default: 1,
    },
    zoomMin: {
      type: Number,
      default: 0.3,
    },
    zoomMax: {
      type: Number,
      default: 2,
    },
    zoomStep: {
      type: Number,
      default: 0.05,
    },
  },
  emits: ['update:modelValue'],
  setup() {
    const { tokenQueryParam } = useImageAuth();
    return {
      tokenQueryParam,
    };
  },
  methods: {
    onSliderChange(val: number) {
      this.$emit('update:modelValue', val);
    },
    zoomIn() {
      if (this.modelValue >= this.zoomMax) return;
      this.$emit('update:modelValue', Math.round((this.modelValue + 0.1) * 100) / 100);
    },
    zoomOut() {
      if (this.modelValue <= this.zoomMin) return;
      this.$emit('update:modelValue', Math.round((this.modelValue - 0.1) * 100) / 100);
    },
    handleDownload() {
      downloadDocumentFile(this.docId, this.filename, this.tokenQueryParam);
    },
  },
});
</script>

<style>
body.body--dark .document-footer .q-slider {
  color: #d5d5d5;
}
body.body--light .document-footer .q-slider {
  color: #7a7a7a;
}
</style>
